const LANE_COLORS   = ['#e8002d','#1a8fff','#00cc55','#ff8800'];
const LANE_COLORS_A = ['rgba(232,0,45,0.14)','rgba(26,143,255,0.14)','rgba(0,204,85,0.14)','rgba(255,136,0,0.14)'];
const KEY_MAP = { 'a':0,'s':1,'d':2,'w':3,'ArrowLeft':0,'ArrowDown':1,'ArrowRight':2,'ArrowUp':3 };

// ═══════════════════════════════════
// STORAGE
// ═══════════════════════════════════
function getProgress() {
  try { return JSON.parse(localStorage.getItem('santes_progress') || '{}'); } catch(e) { return {}; }
}
function saveProgress(data) {
  try { localStorage.setItem('santes_progress', JSON.stringify(data)); } catch(e) {}
}
function getSongData(id) {
  const p = getProgress();
  return p[id] || { stars: 0, bestScore: 0, exUnlocked: false };
}
function setSongData(id, data) {
  const p = getProgress();
  p[id] = { ...getSongData(id), ...data };
  saveProgress(p);
}

// ═══════════════════════════════════
// SCREENS
// ═══════════════════════════════════
function showScreen(id) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById('screen-' + id).classList.add('active');
}

// ═══════════════════════════════════
// TITLE SCREEN — PARTICLES + CONFETTI
// ═══════════════════════════════════
(function initParticles() {
  const c = document.getElementById('title-particles');
  const ctx = c.getContext('2d');
  let W, H, pts = [], confetti = [];
  const CONFETTI_COLORS = ['#c8a84b','#e8002d','#1a3a6e','#006633','#fff','#ff8800'];

  function resize() {
    W = c.width  = c.offsetWidth  || 680;
    H = c.height = c.offsetHeight || 620;
    pts = Array.from({length: 50}, () => ({
      x: Math.random()*W, y: Math.random()*H,
      vx: (Math.random()-0.5)*0.35, vy: (Math.random()-0.5)*0.35,
      r: Math.random()*1.5+0.5, a: Math.random()*0.6+0.1
    }));
    confetti = Array.from({length: 35}, () => ({
      x: Math.random()*W, y: Math.random()*H - H,
      vx: (Math.random()-0.5)*1.2, vy: Math.random()*1.8+0.8,
      rot: Math.random()*360, drot: (Math.random()-0.5)*4,
      col: CONFETTI_COLORS[Math.floor(Math.random()*CONFETTI_COLORS.length)],
      w: 5 + Math.random()*8, h: 3 + Math.random()*5
    }));
  }
  resize();
  window.addEventListener('resize', resize);

  function frame() {
    ctx.clearRect(0, 0, W, H);
    for (const p of pts) {
      p.x += p.vx; p.y += p.vy;
      if (p.x < 0 || p.x > W) p.vx *= -1;
      if (p.y < 0 || p.y > H) p.vy *= -1;
      ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI*2);
      ctx.fillStyle = `rgba(200,168,75,${p.a})`; ctx.fill();
    }
    for (const piece of confetti) {
      piece.x += piece.vx; piece.y += piece.vy; piece.rot += piece.drot;
      if (piece.y > H + 20) { piece.y = -20; piece.x = Math.random() * W; }
      ctx.save(); ctx.translate(piece.x, piece.y); ctx.rotate(piece.rot * Math.PI / 180);
      ctx.fillStyle = piece.col + 'bb';
      ctx.fillRect(-piece.w/2, -piece.h/2, piece.w, piece.h); ctx.restore();
    }
    requestAnimationFrame(frame);
  }
  frame();
})();

// ═══════════════════════════════════
// SONG SELECT
// ═══════════════════════════════════
function buildSongGrid() {
  const grid = document.getElementById('songs-grid');
  grid.innerHTML = '';
  for (const song of SONGS) {
    const sd = getSongData(song.id);
    const card = document.createElement('div');
    card.className = 'song-card';

    const bgDiv = document.createElement('div');
    bgDiv.className = 'song-card-bg';
    bgDiv.style.backgroundImage = `url(${song.bgImage})`;

    const overlay = document.createElement('div'); overlay.className = 'song-card-overlay';

    const info = document.createElement('div'); info.className = 'song-card-info';
    info.innerHTML = `<div class="song-card-title">${song.title}</div>
                      <div class="song-card-meta">${song.artist} · ${Math.floor(song.duration/60)}:${String(Math.floor(song.duration%60)).padStart(2,'0')}</div>`;

    const stars = document.createElement('div'); stars.className = 'song-stars';
    for (let i=1; i<=3; i++) {
      const s = document.createElement('span');
      s.className = 'star ' + (sd.stars >= i ? 'filled' : 'empty');
      s.textContent = '★'; stars.appendChild(s);
    }

    card.appendChild(bgDiv); card.appendChild(overlay); card.appendChild(info); card.appendChild(stars);

    if (sd.exUnlocked) {
      const b = document.createElement('div'); b.className = 'badge-ex'; b.textContent = '2× EX'; card.appendChild(b);
    }
    if (song.locked) {
      const lock = document.createElement('div'); lock.className = 'badge-locked'; lock.textContent = '⚔'; card.appendChild(lock);
    } else {
      card.addEventListener('click', () => startSong(song));
    }
    grid.appendChild(card);
  }
}

// ═══════════════════════════════════
// AUDIO FADE-OUT HELPER
// ═══════════════════════════════════
function stopAudio(aud, fadeMs) {
  if (!aud || typeof aud.pause !== 'function') return;
  // fake timer object has no volume property
  if (aud.volume === undefined) { try { aud.pause(); } catch(e) {} return; }
  const vol0 = aud.volume;
  const steps = 20;
  const dt = (fadeMs || 500) / steps;
  let i = 0;
  const iv = setInterval(() => {
    i++;
    aud.volume = Math.max(0, vol0 * (1 - i/steps));
    if (i >= steps) { clearInterval(iv); try { aud.pause(); aud.currentTime = 0; } catch(e) {} }
  }, dt);
}

// ═══════════════════════════════════
// GAME ENGINE
// ═══════════════════════════════════
let G = {};
const canvas = document.getElementById('game-canvas');
const ctx2   = canvas.getContext('2d');

function resizeCanvas() {
  const area = document.getElementById('canvas-area');
  canvas.width = area.clientWidth; canvas.height = area.clientHeight;
}

function startSong(song, exMode) {
  exMode = exMode || false;
  const sd   = getSongData(song.id);
  const isEx = exMode && sd.exUnlocked;

  // Hard-stop any previous audio NOW (no fade, clean start)
  if (G.audio) { try { G.audio.pause(); if (G.audio.currentTime !== undefined) G.audio.currentTime = 0; } catch(e) {} }
  if (G.animId) { cancelAnimationFrame(G.animId); G.animId = null; }

  G = {
    song, isEx,
    notes: (isEx ? song.notesHard : song.notesEasy).map(n => ({
      time: isEx ? n[0] * 0.5 : n[0], lane: n[1], hit: false, missed: false, _y: -999
    })),
    noteIdx: 0, activeNotes: [],
    score: 0, combo: 0, maxCombo: 0, lives: 3,
    totalNotes: 0, hitCount: 0, perfectCount: 0, greatCount: 0, missCount: 0,
    running: false, audio: null, animId: null, t0: null,
    gameOverPending: false  // flag to avoid double-calling endGame
  };
  G.totalNotes = G.notes.length;

  document.getElementById('hud-song-name').textContent = song.title.toUpperCase() + (isEx ? ' · 2×' : '');
  document.getElementById('hud-score').textContent     = '0';
  document.getElementById('hud-combo').textContent     = '';
  document.getElementById('hud-lives').textContent     = '♥♥♥';
  document.getElementById('hud-acc').textContent       = '';
  document.getElementById('progress-fill').style.width = '0%';

  const vid = document.getElementById('game-video-bg');
  if (vid) vid.src = song.videoSrc || '';

  showScreen('game');
  resizeCanvas();

  // ── AUDIO: must be created synchronously inside user-gesture chain ──
  if (song.audioSrc) {
    const aud = new Audio(song.audioSrc);
    aud.preload = 'auto';
    aud.volume  = 1.0;
    if (isEx) aud.playbackRate = 2.0;
    G.audio = aud;

    const p = aud.play();
    if (p !== undefined) {
      p.then(() => { G.running = true; G.animId = requestAnimationFrame(gameLoop); })
       .catch(err => { console.warn('Audio blocked:', err.message); _startTimer(isEx); });
    } else {
      G.running = true; G.animId = requestAnimationFrame(gameLoop);
    }
  } else {
    _startTimer(isEx);
  }
}

function _startTimer(isEx) {
  G.t0 = performance.now();
  G.audio = { get currentTime(){ return (performance.now()-G.t0)/1000*(isEx?2:1); }, pause(){} };
  G.running = true; G.animId = requestAnimationFrame(gameLoop);
}

const SPEED = 340;
function getHitY() { return canvas.height - 100; }
const HIT_ZONE_HALF = 55;

function spawnNotes(t) {
  const hitY = getHitY();
  while (G.noteIdx < G.notes.length) {
    const n = G.notes[G.noteIdx];
    if (n.time - hitY/SPEED <= t) { G.activeNotes.push(n); G.noteIdx++; } else break;
  }
}

function drawGame(t) {
  const W = canvas.width, H = canvas.height;
  const hitY = getHitY(), LANE_W = W/4, NOTE_H = 46;
  ctx2.clearRect(0,0,W,H);

  for (let i=0; i<4; i++) {
    ctx2.fillStyle = LANE_COLORS_A[i]; ctx2.fillRect(i*LANE_W,0,LANE_W-1,H);
    ctx2.fillStyle = 'rgba(255,255,255,0.025)'; ctx2.fillRect(i*LANE_W+LANE_W-1,0,1,H);
  }
  for (let i=0; i<4; i++) {
    ctx2.fillStyle = 'rgba(255,255,255,0.04)';
    roundRect(ctx2, i*LANE_W+4, hitY-HIT_ZONE_HALF, LANE_W-8, HIT_ZONE_HALF*2, 6); ctx2.fill();
    ctx2.strokeStyle = 'rgba(200,168,75,0.18)'; ctx2.lineWidth = 1;
    roundRect(ctx2, i*LANE_W+4, hitY-HIT_ZONE_HALF, LANE_W-8, HIT_ZONE_HALF*2, 6); ctx2.stroke();
  }
  ctx2.fillStyle = 'rgba(200,168,75,0.25)'; ctx2.fillRect(0,hitY-1,W,2);

  for (const n of G.activeNotes) {
    if (n.hit||n.missed) continue;
    const y = hitY - (n.time-t)*SPEED - NOTE_H/2;
    n._y = y + NOTE_H/2;
    const nx = n.lane*LANE_W+5, nW = LANE_W-10;
    ctx2.shadowColor = LANE_COLORS[n.lane]; ctx2.shadowBlur = 18;
    ctx2.fillStyle = LANE_COLORS[n.lane];
    roundRect(ctx2,nx,y,nW,NOTE_H,7); ctx2.fill();
    ctx2.shadowBlur = 0;
    ctx2.fillStyle = 'rgba(255,255,255,0.2)';
    roundRect(ctx2,nx+2,y+2,nW-4,NOTE_H*0.36,5); ctx2.fill();
    ctx2.fillStyle='rgba(255,255,255,0.35)'; ctx2.save();
    ctx2.translate(nx+nW/2, y+NOTE_H/2); ctx2.rotate(Math.PI/4);
    ctx2.fillRect(-3.5,-3.5,7,7); ctx2.restore();
  }

  // Auto-miss
  for (const n of G.activeNotes) {
    if (!n.hit && !n.missed && n._y > hitY+HIT_ZONE_HALF+30) {
      n.missed = true; G.missCount++; G.combo = 0; G.lives--;
      updateHUD(); flashLane(n.lane,'miss');
      if (G.lives <= 0 && !G.gameOverPending) {
        G.gameOverPending = true;
        G.running = false; cancelAnimationFrame(G.animId);
        stopAudio(G.audio, 500);          // ← music fades out on fail
        setTimeout(() => endGame(), 550);
        return;
      }
    }
  }
}

function roundRect(ctx,x,y,w,h,r) {
  ctx.beginPath(); ctx.moveTo(x+r,y); ctx.lineTo(x+w-r,y);
  ctx.quadraticCurveTo(x+w,y,x+w,y+r); ctx.lineTo(x+w,y+h-r);
  ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h); ctx.lineTo(x+r,y+h);
  ctx.quadraticCurveTo(x,y+h,x,y+h-r); ctx.lineTo(x,y+r);
  ctx.quadraticCurveTo(x,y,x+r,y); ctx.closePath();
}

function gameLoop() {
  if (!G.running) return;
  const t = G.audio ? G.audio.currentTime : 0;
  spawnNotes(t); drawGame(t);
  const dur = G.isEx ? G.song.duration*0.5 : G.song.duration;
  document.getElementById('progress-fill').style.width = Math.min(t/dur*100,100)+'%';
  // Level complete
  if (t >= dur && G.noteIdx >= G.notes.length && G.activeNotes.every(n=>n.hit||n.missed)) {
    G.running = false; cancelAnimationFrame(G.animId);
    stopAudio(G.audio, 400);             // ← music fades out on win
    setTimeout(() => endGame(), 450);
    return;
  }
  G.animId = requestAnimationFrame(gameLoop);
}

function tapLane(lane, e) {
  if (e) e.preventDefault();
  if (!G.running) return;
  const hitY = getHitY();
  let best = null, bestDist = Infinity;
  for (const n of G.activeNotes) {
    if (n.hit||n.missed||n.lane!==lane) continue;
    const dist = Math.abs(n._y-hitY);
    if (dist < bestDist) { bestDist=dist; best=n; }
  }
  if (best && bestDist <= HIT_ZONE_HALF+20) {
    best.hit=true; G.hitCount++; G.combo++;
    if (G.combo>G.maxCombo) G.maxCombo=G.combo;
    const pts = bestDist<HIT_ZONE_HALF*0.35?300:bestDist<HIT_ZONE_HALF*0.7?200:100;
    if (pts===300) G.perfectCount++; else if (pts>=200) G.greatCount++;
    G.score += pts * Math.min(G.combo,10);
    const label = pts===300?'PERFECT':pts===200?'GREAT':'OK';
    const col   = pts===300?'#f5e0a0':pts===200?'#6ae0ff':'#ffffff';
    showFeedback(lane,label,col); flashLane(lane,'hit'); updateHUD();
  } else { flashLane(lane,'miss'); }
}

function flashLane(lane,type) {
  const el = document.getElementById('lt'+lane);
  el.classList.add(type==='hit'?'hit':'miss-flash');
  setTimeout(()=>el.classList.remove('hit','miss-flash'),130);
}

function showFeedback(lane,text,color) {
  const area = document.getElementById('canvas-area');
  const lW = canvas.width/4;
  const el = document.createElement('div');
  el.className='feedback'; el.style.color=color;
  el.style.left=(lane*lW+lW/2-40)+'px'; el.style.top=(getHitY()-70)+'px';
  el.textContent=text; area.appendChild(el);
  setTimeout(()=>el.remove(),560);
}

function updateHUD() {
  document.getElementById('hud-score').textContent = G.score.toLocaleString();
  const c = document.getElementById('hud-combo');
  c.textContent = G.combo>1?'×'+G.combo:'';
  c.classList.remove('pop'); void c.offsetWidth; if(G.combo>1) c.classList.add('pop');
  document.getElementById('hud-lives').textContent = ['','♥','♥♥','♥♥♥'][Math.max(0,G.lives)];
  const acc = G.hitCount>0?Math.round(G.hitCount/(G.hitCount+G.missCount)*100):100;
  document.getElementById('hud-acc').textContent = acc+'%';
}

function endGame() {
  G.running = false; cancelAnimationFrame(G.animId);
  // make absolutely sure audio is stopped
  if (G.audio) { try { G.audio.pause(); if(G.audio.currentTime!==undefined) G.audio.currentTime=0; } catch(e) {} }

  const hitPct   = G.totalNotes > 0 ? G.hitCount/G.totalNotes : 0;
  const stars    = hitPct>=0.95?3:hitPct>=0.75?2:hitPct>=0.5?1:0;
  const sd       = getSongData(G.song.id);
  const unlockEx = !G.isEx && stars===3 && !sd.exUnlocked;

  setSongData(G.song.id, {
    stars: Math.max(sd.stars,stars), bestScore: Math.max(sd.bestScore,G.score),
    exUnlocked: sd.exUnlocked||unlockEx
  });

  document.getElementById('res-song').textContent    = G.song.title.toUpperCase();
  document.getElementById('res-score').textContent   = G.score.toLocaleString();
  document.getElementById('res-perfect').textContent = G.perfectCount;
  document.getElementById('res-great').textContent   = G.greatCount;
  document.getElementById('res-miss').textContent    = G.missCount;

  const starsEl = document.getElementById('res-stars'); starsEl.textContent='';
  for (let i=1;i<=3;i++) {
    const s=document.createElement('span');
    s.style.color=stars>=i?'#c8a84b':'#2a2a2a'; s.textContent='★'; starsEl.appendChild(s);
  }

  const banner = document.getElementById('unlock-banner');
  if (unlockEx) { banner.textContent='✦ Has desbloquejat el MODE EX 2×!'; banner.classList.add('show'); }
  else banner.classList.remove('show');

  const retryBtn = document.getElementById('btn-res-retry');
  const newSd = getSongData(G.song.id);
  if (newSd.exUnlocked && !G.isEx) {
    retryBtn.textContent='MODE EX 2× ▶'; retryBtn.onclick=()=>startSong(G.song,true);
  } else {
    retryBtn.textContent='TORNAR A JUGAR'; retryBtn.onclick=()=>startSong(G.song,G.isEx);
  }
  showScreen('result');
}

// ═══════════════════════════════════
// KEYBOARD
// ═══════════════════════════════════
const keysHeld = new Set();
document.addEventListener('keydown', e => {
  if (keysHeld.has(e.key)) return; keysHeld.add(e.key);
  const lane = KEY_MAP[e.key];
  if (lane !== undefined) { e.preventDefault(); tapLane(lane,null); }
});
document.addEventListener('keyup', e => keysHeld.delete(e.key));
document.getElementById('lane-bar').addEventListener('touchstart', e=>e.preventDefault(), {passive:false});

// ═══════════════════════════════════
// NAVIGATION
// ═══════════════════════════════════
document.getElementById('btn-play').addEventListener('click', ()=>{ buildSongGrid(); showScreen('select'); });
document.getElementById('btn-back-select').addEventListener('click', ()=>showScreen('title'));
document.getElementById('btn-res-menu').addEventListener('click', ()=>{ buildSongGrid(); showScreen('select'); });
window.addEventListener('resize', ()=>{ if(document.getElementById('screen-game').classList.contains('active')) resizeCanvas(); });